async () => {
  const base = '/!api/2.0/repositories/healshealthcare/heals-app-rn/pullrequests/540';
  const [prRes, diffstatRes] = await Promise.all([
    fetch(base, { credentials: 'include' }),
    fetch(`${base}/diffstat?pagelen=100`, { credentials: 'include' }),
  ]);
  const prText = await prRes.text();
  const diffstatText = await diffstatRes.text();
  let pr;
  let diffstat;
  try { pr = JSON.parse(prText); } catch { pr = { raw: prText.slice(0, 500) }; }
  try { diffstat = JSON.parse(diffstatText); } catch { diffstat = { raw: diffstatText.slice(0, 500) }; }
  return {
    statuses: { pr: prRes.status, diffstat: diffstatRes.status },
    pr: {
      id: pr.id,
      title: pr.title,
      state: pr.state,
      source: pr.source && { branch: pr.source.branch?.name, hash: pr.source.commit?.hash },
      destination: pr.destination && { branch: pr.destination.branch?.name, hash: pr.destination.commit?.hash },
      merge_commit: pr.merge_commit?.hash,
      close_source_branch: pr.close_source_branch,
      updated_on: pr.updated_on,
    },
    diffstat: Array.isArray(diffstat.values) ? diffstat.values.map(v => ({
      status: v.status,
      old: v.old?.path,
      new: v.new?.path,
      lines_added: v.lines_added,
      lines_removed: v.lines_removed,
    })) : diffstat,
    next: diffstat.next,
  };
}
